WITH stats AS (
SELECT
CASE
WHEN turnover_days > 360 THEN 'over360'
WHEN turnover_days BETWEEN 270 AND 360 THEN 'd270_360'
WHEN turnover_days BETWEEN 210 AND 270 THEN 'd210_270'
WHEN turnover_days BETWEEN 150 AND 210 THEN 'd150_210'
WHEN turnover_days BETWEEN 120 AND 150 THEN 'd120_150'
WHEN turnover_days BETWEEN 60 AND 120 THEN 'd60_120'
ELSE 'under60'
END as turnover_range,
COUNT(distinct asin) as skuCount,
SUM(total_inventory_value) as inventoryValue,
SUM(
CAST(
CASE
WHEN LEFT(sales_amount, 2) = '$-'
THEN -1 * CAST(REPLACE(REPLACE(SUBSTRING(sales_amount, 3), ',', ''), ' ', '') AS DECIMAL(10,2))
WHEN LEFT(sales_amount, 1) = '$'
THEN CAST(REPLACE(REPLACE(SUBSTRING(sales_amount, 2), ',', ''), ' ', '') AS DECIMAL(10,2))
ELSE 0
END * 6.8 AS DECIMAL(10,2)
)
) / 7 as revenue,
SUM(
CAST(
CASE
WHEN LEFT(gross_profit, 2) = '$-'
THEN -1 * CAST(REPLACE(REPLACE(SUBSTRING(gross_profit, 3), ',', ''), ' ', '') AS DECIMAL(10,2))
WHEN LEFT(gross_profit, 1) = '$'
THEN CAST(REPLACE(REPLACE(SUBSTRING(gross_profit, 2), ',', ''), ' ', '') AS DECIMAL(10,2))
ELSE 0
END * 6.8 AS DECIMAL(10,2)
)
) / 7 as profit
FROM amz_data_analysis_turnover_mskulist


