    and turnover_days le #{turnoverDaysMax}
    and is_delete = 0
    and DATE(created_at) = CURDATE()

)
SELECT
s.turnover_range,
s.skuCount,
s.skuCount / t.total_count * 100 as skuRatio,
s.inventoryValue,
s.inventoryValue / t.total_value * 100 as inventoryRatio,
s.revenue,
CASE WHEN t.total_revenue > 0 THEN s.revenue / t.total_revenue * 100 ELSE 0 END as revenueRatio,
s.profit,
CASE WHEN t.total_profit > 0 THEN s.profit / t.total_profit * 100 ELSE 0 END as profitRatio,
CASE WHEN s.revenue > 0 THEN s.profit / s.revenue * 100 ELSE 0 END as profitMargin
FROM stats s, totals t
ORDER BY
CASE s.turnover_range
WHEN 'over360' THEN 1
WHEN 'd270_360' THEN 2
WHEN 'd210_270' THEN 3
WHEN 'd150_210' THEN 4
WHEN 'd120_150' THEN 5
WHEN 'd60_120' THEN 6
ELSE 7
END

